@JvmName("step25584")
fun step25584(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 16
}
data class Pair25585<A, B>(val first: A, val second: B)

fun combine25585(left: Int, right: Int): Pair25585<Int, Int> {
    return Pair25585(left + 23, right + 36)
}
class Counter25586 {
    var current: Int by Delegates.observable(30) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
